-- The WhatsApp messages' campaign / template names in the code are neutral now (Phase 3). The Sample Institute's
-- were approved under techcadd's names: it keeps them, as its own settings. Only the names it has not set itself.
UPDATE app_config SET config = jsonb_set(config, '{campaigns}',
  '{"fee_reminder": "techcadd_installment_reminder", "enquiry_thanks": "techcadd_enquiry_thanks", "visit_thanks": "techcadd_visit_thanks", "registration": "techcadd_registration_done", "certificate": "techcadd_certificate_issued"}'::jsonb
    || coalesce(nullif(config->'campaigns', 'null'::jsonb), '{}'::jsonb))
WHERE org_id = '00000000-0000-4000-8000-000000000001' AND key = 'whatsapp';
--> statement-breakpoint
-- Certificate designs drew techcadd's logo file (public/tce-logo.png, which goes): they now draw the institute's own
-- logo (BRAND_LOGO in lib/cert-design.ts), whichever institute's design it is.
UPDATE certificate_designs SET design = replace(design::text, '"/tce-logo.png"', '"brand:logo"')::jsonb
WHERE design::text LIKE '%"/tce-logo.png"%';
--> statement-breakpoint
-- The details the student ID card printed from the code (lib/id-card.ts) are the Sample Institute's own contacts now.
UPDATE organisations SET branding = coalesce(branding, '{}'::jsonb) || jsonb_build_object('contact', jsonb_build_object(
  'address', 'Corporate Office : Plot number F-547, 3rd floor, Industrial Area, 8A, Sector 75, Sahibzada Ajit Singh Nagar, Punjab 160055',
  'phone', '+91 9888122206', 'website', 'www.techcadd.com', 'social', 'https://www.instagram.com/techcadd_india/'))
WHERE id = '00000000-0000-4000-8000-000000000001' AND NOT (coalesce(branding, '{}'::jsonb) ? 'contact');
--> statement-breakpoint
-- The Sample Institute's main letter company printed on techcadd's letterhead and stamp files (public/letterhead.jpg,
-- public/letters/stamp-signature.png, which go): they become its uploaded images, unless it has uploaded its own.
UPDATE letter_companies SET letterhead = decode('', 'base64'), letterhead_mime = 'image/jpeg'
WHERE org_id = '00000000-0000-4000-8000-000000000001' AND is_default AND letterhead IS NULL;
--> statement-breakpoint
UPDATE letter_companies SET stamp = decode('', 'base64'), stamp_mime = 'image/png'
WHERE org_id = '00000000-0000-4000-8000-000000000001' AND is_default AND stamp IS NULL;
